import hashlib

def enabled_users(flag, users, percent):
    def bucket(user):
        digest = hashlib.sha256((flag + ":" + user).encode("utf-8")).hexdigest()
        return int(digest[:8], 16) % 10000
    return [u for u in users if bucket(u) < percent * 100]

