cicd-freeze-window.solution:
import datetime

def can_deploy(when, windows, blocked_weekdays, emergency):
    inside = [w for w in windows if w[0] <= when < w[1]]
    if emergency:
        return all(w[2] for w in inside)
    if inside:
        return False
    weekday = datetime.datetime.strptime(when, "%Y-%m-%dT%H:%M").weekday()
    return weekday not in blocked_weekdays

cicd-required-checks.description:
A hosting platform decides whether a pull request may be merged. Return the list of reasons that block the
merge; an empty list means it may be merged.

`pr` is a dictionary with:

- `"author"`: the author's name;
- `"approvals"`: a list of names of people who approved (names may repeat);
- `"checks"`: a list of `[name, state]` pairs in the order the results were reported. A check may be reported
  several times (for example after a re-run); only its **latest** state counts. States are `"success"`,
  `"failure"`, `"pending"` and `"skipped"`;
- `"base"`: the commit of the main branch that the pull request was last updated from;
- `"unresolved"`: the number of unresolved review conversations.

`rules` is a dictionary with:

- `"min_approvals"`: how many **distinct** approvers other than the author are required;
- `"required_checks"`: names of the checks that must pass. A check passes if its latest state is `"success"`
  or `"skipped"`. A required check that was never reported does not pass;
- `"require_up_to_date"`: if true, `pr["base"]` must equal `rules["main_head"]`;
- `"main_head"`: the current tip of the main branch.

Blocking reasons, as strings:

- `"approvals"` — not enough valid approvals;
- `"check:<name>"` — one per required check that does not pass;
- `"outdated"` — the branch must be up to date and is not;
- `"conversations"` — there is at least one unresolved conversation.

Return the reasons sorted alphabetically.

**Example 1:** author `"ana"`, approvals `["ben"]`, checks `[["lint","success"],["unit","success"]]`, base `"c1"`,
unresolved `0`; rules: 1 approval, required `["lint","unit"]`, up to date required, main head `"c1"` → `[]`

**Example 2:** the same pull request but approvals `["ana"]` and checks `[["lint","success"]]` → `["approvals", "check:unit"]`

cicd-required-checks.solution:
def merge_blockers(pr, rules):
    reasons = []
    approvers = {a for a in pr["approvals"] if a != pr["author"]}
    if len(approvers) < rules["min_approvals"]:
        reasons.append("approvals")
    latest = {}
    for name, state in pr["checks"]:
        latest[name] = state
    for name in set(rules["required_checks"]):
        if latest.get(name) not in ("success", "skipped"):
            reasons.append("check:" + name)
    if rules["require_up_to_date"] and pr["base"] != rules["main_head"]:
        reasons.append("outdated")
    if pr["unresolved"] > 0:
        reasons.append("conversations")
    return sorted(reasons)

cicd-blue-green-fsm.solution:
def blue_green(commands):
    version = {"blue": "v0", "green": None}
    verified = {"blue": True, "green": False}
    live, can_rollback, rejected = "blue", False, 0
    for command in commands:
        idle = "green" if live == "blue" else "blue"
        kind = command[0]
        if kind == "deploy":
            version[idle] = command[1]
            verified[idle] = False
            can_rollback = False
        elif kind == "verify":
            if version[idle] is None:
                rejected += 1
            else:
                verified[idle] = command[1] == "pass"
        elif kind == "switch":
            if verified[idle]:
                verified[live] = True
                live = idle
                can_rollback = True
            else:
                rejected += 1
        elif kind == "rollback":
            if can_rollback:
                live = idle
                can_rollback = False
            else:
                rejected += 1
    return [live, version[live], rejected]

cicd-canary-decision.solution:
def canary_decision(baseline, canary, config):
    def totals(samples):
        return sum(s[0] for s in samples), sum(s[1] for s in samples)
    b_req, b_err = totals(baseline)
    c_req, c_err = totals(canary)
    if c_req < config["min_requests"]:
        return "wait"
    b_rate = b_err / b_req if b_req else 0.0
    c_rate = c_err / c_req if c_req else 0.0
    if c_rate > config["abs_ceiling"]:
        return "rollback"
    if c_rate > b_rate * config["max_ratio"] + config["margin"]:
        return "rollback"
    return "promote"

cicd-rollback-target.solution:
def rollback_target(releases, compat):
    if not releases:
        return None
    current_version, _, current_schema = releases[-1]
    for version, status, schema in reversed(releases[:-1]):
        if status == "succeeded" and version != current_version and current_schema - schema <= compat:
            return version
    return None

cicd-migration-plan.solution:
def first_unsafe_step(columns, app, steps):
    existing = set(columns)
    running = set(app)
    previous = set(app)
    for index, step in enumerate(steps, 1):
        kind = step[0]
        if kind == "add":
            if step[1] in existing:
                return index
            existing.add(step[1])
        elif kind == "drop":
            if step[1] not in existing:
                return index
            existing.discard(step[1])
        else:
            previous = running
            running = set(step[1])
        if not running <= existing or not previous <= existing:
            return index
    return 0

cicd-dora-metrics.solution:
def dora_metrics(deployments, incidents, days):
    frequency = len(deployments) / days
    leads = sorted(finished - c for _, finished, commits in deployments for c in commits)
    if leads:
        mid = len(leads) // 2
        lead = float(leads[mid]) if len(leads) % 2 else (leads[mid - 1] + leads[mid]) / 2
    else:
        lead = 0.0
    failed = {i[0] for i in incidents}
    failure_rate = len(failed) / len(deployments) if deployments else 0.0
    restores = [resolved - started for _, started, resolved in incidents]
    restore = sum(restores) / len(restores) if restores else 0.0
    return [frequency, lead, failure_rate, restore]

cicd-git-bisect.solution:
def bisect_commits(bad):
    good, broken = 0, len(bad) - 1
    tested = []
    while broken - good > 1:
        mid = (good + broken) // 2
        tested.append(mid)
        if bad[mid]:
            broken = mid
        else:
            good = mid
    return [broken, tested]

cicd-revert-selection.solution:
def commits_to_revert(results):
    if not results:
        return []
    last = len(results) - 1
    culprits = set()
    for j in range(len(results[0])):
        if results[last][j]:
            continue
        i = last
        while i >= 1 and not results[i - 1][j]:
            i -= 1
        if i >= 1:
            culprits.add(i)
    return sorted(culprits)

cicd-merge-queue.solution:
def merge_queue(queue, bad, batch_size):
    bad_set = set(bad)
    merged, ejected = [], []
    runs = 0
    for start in range(0, len(queue), batch_size):
        stack = [queue[start:start + batch_size]]
        while stack:
            group = stack.pop()
            runs += 1
            if not any(c in bad_set for c in group):
                merged.extend(group)
            elif len(group) == 1:
                ejected.append(group[0])
            else:
                half = len(group) // 2
                stack.append(group[half:])
                stack.append(group[:half])
    return [merged, ejected, runs]

cicd-flaky-tests.solution:
def classify_tests(runs):
    commit_order = {}
    outcomes = {}
    for commit, test, passed in runs:
        if commit not in commit_order:
            commit_order[commit] = len(commit_order)
        outcomes.setdefault(test, {}).setdefault(commit, set()).add(bool(passed))
    result = []
    for test in sorted(outcomes):
        by_commit = outcomes[test]
        if any(len(seen) == 2 for seen in by_commit.values()):
            status = "flaky"
        else:
            latest = max(by_commit, key=lambda c: commit_order[c])
            status = "broken" if by_commit[latest] == {False} else "healthy"
        result.append([test, status])
    return result
